s=s.replace(".eyebrow{color:var(--rose);", "@keyframes screen-in{from{opacity:0}to{opacity:1}}@keyframes card-in{from{opacity:0;transform:translateY(22px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes photo-in{from{opacity:0;transform:translateY(28px) scale(.92) rotate(var(--tilt))}to{opacity:1;transform:translateY(0) scale(1) rotate(var(--tilt))}}@keyframes photo-drift{0%,100%{translate:0 0}50%{translate:0 -7px}}@keyframes heart-rise{0%{opacity:0;transform:translateY(20px) scale(.55) rotate(-12deg)}15%{opacity:1}100%{opacity:0;transform:translateY(-105vh) scale(1.45) rotate(18deg)}}\n    .screen.active .card{animation:card-in .8s cubic-bezier(.2,.8,.2,1) both}.eyebrow{color:var(--rose);")
