s=s.replace("document.getElementById('music2').addEventListener('click',()=>{stopAudio();audios[2].play().catch(()=>{})});", "document.getElementById('music2').addEventListener('click',()=>playFrom(audios[2],0));\n    function makeHearts(){const rain=document.createElement('div');rain.className='heart-rain';rain.setAttribute('aria-hidden','true');document.body.appendChild(rain);for(let i=0;i<34;i++){const heart=document.createElement('span');heart.textContent=['♥','♡','💕'][i%3];heart.style.setProperty('--left',`${Math.random()*100}%`);heart.style.setProperty('--size',`${18+Math.random()*28}px`);heart.style.setProperty('--duration',`${4+Math.random()*5}s`);heart.style.animationDelay=`${Math.random()*2}s`;rain.appendChild(heart)}setTimeout(()=>rain.remove(),12000)}")
